192: void Algo_Breath_StepGuide(uint32_t dt_ms, uint8_t target_bpm, BreathGuideOut_t *out)
193: {
194:     uint32_t cycle_ms;
195:     uint32_t inhale_ms;
196:     uint32_t exhale_ms;
197: 
198:     if (out == NULL) return;
199:     memset(out, 0, sizeof(*out));
200: 
201:     if (s_phase == BREATH_PHASE_IDLE)
202:     {
203:         out->phase = BREATH_PHASE_IDLE;
204:         out->lung_pct = 0U;
205:         out->guide_bpm = target_bpm;
206:         out->real_cbpm = s_real_cbpm;
207:         out->calib_ready = s_calib_ready;
208:         return;
209:     }
210: 
211:     if (target_bpm < GBPM_MIN) target_bpm = GBPM_MIN;
212:     if (target_bpm > GBPM_MAX) target_bpm = GBPM_MAX;
213: 
214:     if (s_phase_elapsed_ms == 0U && s_phase == BREATH_PHASE_INHALE)
215:     {
216:         /* Latch new BPM smoothly at start of inhale cycle */
217:         s_active_bpm = target_bpm;
218:         out->phase_changed = 1U;
219:     }
220: 
221:     s_phase_elapsed_ms += dt_ms;
222:     cycle_ms  = 60000UL / (uint32_t)s_active_bpm;
223:     inhale_ms = (cycle_ms * 4U) / 10U; /* Strict 4:6 inhale/exhale ratio */
224:     exhale_ms = cycle_ms - inhale_ms;
225: 
226:     if (s_phase == BREATH_PHASE_INHALE)
227:     {
228:         if (s_phase_elapsed_ms >= inhale_ms)
229:         {
230:             s_phase = BREATH_PHASE_EXHALE;
231:             s_phase_elapsed_ms = 0U;
232:             out->phase_changed = 1U;
233:             out->lung_pct = 100U;
234:         }
235:         else
236:         {
237:             out->lung_pct = (uint8_t)((s_phase_elapsed_ms * 100UL) / inhale_ms);
238:         }
239:     }
240:     else /* BREATH_PHASE_EXHALE */
241:     {
242:         if (s_phase_elapsed_ms >= exhale_ms)
243:         {
244:             s_phase = BREATH_PHASE_INHALE;
245:             s_phase_elapsed_ms = 0U;
246:             s_active_bpm = target_bpm;
247:             out->phase_changed = 1U;
248:             out->lung_pct = 0U;
249:         }
250:         else
251:         {
252:             uint32_t down = (s_phase_elapsed_ms * 100UL) / exhale_ms;
253:             out->lung_pct = (down <= 100U) ? (uint8_t)(100U - down) : 0U;
254:         }
255:     }
256: 
