118: void Algo_Breath_FeedSample(uint16_t raw_adc, uint32_t now_ms)
119: {
120:     float raw = (float)raw_adc;
121:     float ac;
122:     float k_recent; /* Rising slope after valley */
123:     float k_prev;   /* Falling slope into valley */
124:     float valley_val;
125:     float th;
126:     uint32_t n;
127: 
128:     if (s_sample_cnt == 0U)
129:     {
130:         s_baseline = raw;
131:     }
132:     s_baseline = 0.98f * s_baseline + 0.02f * raw;
133:     ac = raw - s_baseline;
134:     s_lpf = 0.75f * s_lpf + 0.25f * ac;
135: 
136:     s_buf[s_sample_cnt % BREATH_BUF_LEN] = s_lpf;
137:     s_sample_cnt++;
138:     if (s_sample_cnt < 9U) return;
139: 
140:     n = s_sample_cnt;
141:     /* PDF eq: averaged 1st-order differences around candidate valley fmin at (n-5) */
142:     k_recent = (s_buf[(n - 1U) % BREATH_BUF_LEN] + s_buf[(n - 2U) % BREATH_BUF_LEN]
143:               - s_buf[(n - 3U) % BREATH_BUF_LEN] - s_buf[(n - 4U) % BREATH_BUF_LEN]) * 0.5f;
144:     k_prev   = (s_buf[(n - 5U) % BREATH_BUF_LEN] + s_buf[(n - 6U) % BREATH_BUF_LEN]
145:               - s_buf[(n - 7U) % BREATH_BUF_LEN] - s_buf[(n - 8U) % BREATH_BUF_LEN]) * 0.5f;
146: 
147:     valley_val = s_buf[(n - 5U) % BREATH_BUF_LEN];
148:     s_amp_env = 0.98f * s_amp_env + 0.02f * fabsf(s_lpf);
149:     th = s_amp_env * 0.25f;
150:     if (th < VALLEY_AMP_MIN_THRESH) th = VALLEY_AMP_MIN_THRESH;
151: 
152:     /* Valid valley: falling before (k_prev < 0), rising after (k_recent > 0), and below negative threshold */
153:     if (k_prev < 0.0f && k_recent > 0.0f && valley_val < -th)
154:     {
155:         on_valid_valley(now_ms);
156:     }
157: }
