        if ($null -ne $curUser) {
            $replyStr = ($curReplies | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join "`n`n"
            $rounds.Add(@{ User = $curUser; Reply = $replyStr })
            $curReplies.Clear()
        }
        $curUser = $entry
